    "pdfUrl": "https://drive.google.com/file/d/135PtijGbpOI2kf0Xi88LWcYMqIlbUI0J/view",
    "content": "২০২৭ সালের এসএসসি পরীক্ষার জন্য জাতীয় শিক্ষাক্রম ও পাঠ্যপুস্তক বোর্ড (NCTB) কর্তৃক বিষয়ভিত্তিক মূল্যায়ন নির্দেশনা ও নম্বর বিভাজন চূড়ান্ত করে প্রকাশ করা হয়েছে। এই সিলেবাস ২০২৫ সালে ৯ম শ্রেণিতে অধ্যয়নরত এবং ২০২৭ সালের এসএসসি পরীক্ষায় অংশগ্রহণকারী সকল শিক্ষার্থীর জন্য প্রযোজ্য।\n\n### অফিসিয়াল ৩টি খণ্ডের সিলেবাস PDF ডাউনলোড লিংক:\n১. **খণ্ড ১ (আবশ্যিক ও সাধারণ বিষয়সমূহ):** [পার্ট-১ PDF ডাউনলোড করুন](https://drive.google.com/file/d/135PtijGbpOI2kf0Xi88LWcYMqIlbUI0J/view)\n২. **খণ্ড ২ (বিজ্ঞান ও কারিগরি বিষয়সমূহ):** [পার্ট-২ PDF ডাউনলোড করুন](https://drive.google.com/file/d/131hgufsoekk3x4LSESr2jF6yrqZmxfD3/view)\n৩. **খণ্ড ৩ (মানবিক ও ব্যবসায় শিক্ষা বিষয়সমূহ):** [পার্ট-৩ PDF ডাউনলোড করুন](https://drive.google.com/file/d/1jqCocawEYug-ljl9WyWLc5ecuqPZYZ6z/view)\n\n### পাঠ্যসূচির প্রধান বৈশিষ্ট্য:\n- নতুন কারিকুলাম ও পরিমার্জিত শিখনফল অনুযায়ী পাঠ্যবইয়ের অধ্যায়ভিত্তিক বিভাজন।\n- শিখনকালীন ধারাবাহিক মূল্যায়ন এবং পাবলিক পরীক্ষার লিখিত মূল্যায়নের স্পষ্ট ভারসাম্য।\n- সৃজনশীল ও ব্যবহারিক অংশের বাস্তবসম্মত প্রশ্ন কাঠামো।",
    "faq": [
      {
        "q": "২০২৭ সালের এসএসসি সিলেবাস কাদের জন্য প্রযোজ্য?",
        "a": "যারা ২০২৫-২০২৬ শিক্ষাবর্ষে ৯ম ও ১০ম শ্রেণিতে পড়ছে এবং ২০২৭ সালে এসএসসি পরীক্ষা দেবে, তাদের জন্য এই পরিমার্জিত সিলেবাস প্রযোজ্য।"
      },
      {
        "q": "সিলেবাসের সব খণ্ড কি বিনামূল্যে ডাউনলোড করা যায়?",
        "a": "হ্যাঁ, তিনটি খণ্ডের সবকয়টি গুগল ড্রাইভ লিংক থেকে সম্পূর্ণ বিনামূল্যে ও দ্রুত ডাউনলোড করা যাবে।"
      }
    ]
